import pandas as pd
from collections import defaultdict, Counter
import re
from typing import Dict, List, Set, Tuple

def normalize_text(text: str) -> str:
    """Normalize text."""
    text = text.strip().lower()
    text = re.sub(r'[&/]', ' and ', text)
    text = re.sub(r'[^a-z0-9\s]', '', text)
    text = re.sub(r'\s+', ' ', text)
    return text

def load_categories():
    """Load all categories."""
    all_data = []
    for source, filepath in [('amazon', '/root/data/amazon_product_categories.csv'),
                             ('facebook', '/root/data/fb_product_categories.csv'),
                             ('google', '/root/data/google_shopping_product_categories.csv')]:
        df = pd.read_csv(filepath)
        for path in df['category_path']:
            parts = [p.strip() for p in path.split('>')]
            all_data.append({'source': source, 'path': path, 'parts': parts, 'depth': len(parts)})
    return all_data

def build_unified_taxonomy(all_data: List[Dict]):
    """Build unified taxonomy by analyzing hierarchy."""
    unified = {}

    # Level 1: Top level categories
    level1_counter = Counter()
    level1_names = {}
    for entry in all_data:
        norm = normalize_text(entry['parts'][0])
        level1_counter[norm] += 1
        if norm not in level1_names:
            level1_names[norm] = entry['parts'][0]

    # Keep top 18
    level1_list = {}
    for norm, _ in level1_counter.most_common(18):
        level1_list[norm] = level1_names[norm]
    unified[1] = level1_list

    # For levels 2-5, build hierarchically
    for level in range(2, 6):
        level_children = defaultdict(Counter)
        level_names = defaultdict(str)

        for entry in all_data:
            if level <= len(entry['parts']):
                parent_norm = normalize_text(entry['parts'][level - 2])
                child_norm = normalize_text(entry['parts'][level - 1])
                child_orig = entry['parts'][level - 1]

                level_children[parent_norm][child_norm] += 1
                if not level_names[child_norm]:
                    level_names[child_norm] = child_orig

        # Build level items
        level_items = {}
        for parent_norm, children in level_children.items():
            for child_norm, count in children.most_common(10):
                if child_norm not in level_items:
                    level_items[child_norm] = (level_names[child_norm], count)

        # Keep top items
        sorted_items = sorted(level_items.items(), key=lambda x: x[1][1], reverse=True)
        top_n = min(len(sorted_items), max(40, 12 * (6 - level)))

        level_unified = {}
        for norm, (name, _) in sorted_items[:top_n]:
            level_unified[norm] = name
        unified[level] = level_unified

    return unified

def map_category(entry: Dict, unified: Dict) -> Dict:
    """Map category to unified taxonomy."""
    result = {'source': entry['source'], 'category_path': entry['path'], 'depth': entry['depth']}

    for level in range(1, 6):
        if level <= len(entry['parts']):
            part = entry['parts'][level - 1]
            norm = normalize_text(part)

            if norm in unified[level]:
                result[f'unified_level_{level}'] = unified[level][norm]
            else:
                # Find best match
                best_match = None
                best_score = 0
                norm_words = set(norm.split())

                for unified_norm, unified_name in unified[level].items():
                    unified_words = set(unified_norm.split())
                    overlap = len(norm_words & unified_words)
                    if overlap > best_score:
                        best_score = overlap
                        best_match = unified_name

                result[f'unified_level_{level}'] = best_match if best_match else list(unified[level].values())[0] if unified[level] else None
        else:
            result[f'unified_level_{level}'] = None

    return result

def main():
    print("Loading categories...")
    all_data = load_categories()
    print(f"Loaded {len(all_data)} categories")

    print("Building unified taxonomy...")
    unified = build_unified_taxonomy(all_data)

    print("Mapping categories...")
    results = []
    for i, entry in enumerate(all_data):
        if (i + 1) % 2000 == 0:
            print(f"  Processed {i + 1}/{len(all_data)}")
        results.append(map_category(entry, unified))

    df = pd.DataFrame(results)
    df.to_csv('/root/output/unified_taxonomy_full.csv', index=False)
    print(f"Saved {len(df)} mappings")

    print("\nStatistics:")
    for level in range(1, 6):
        print(f"Level {level}: {df[f'unified_level_{level}'].nunique()} categories")

    print("Building hierarchy...")
    hierarchy = []
    seen = set()
    for _, row in df.iterrows():
        key = tuple(row[f'unified_level_{i}'] for i in range(1, 6))
        if key not in seen:
            seen.add(key)
            hierarchy.append({f'unified_level_{i}': key[i-1] for i in range(1, 6)})

    pd.DataFrame(hierarchy).to_csv('/root/output/unified_taxonomy_hierarchy.csv', index=False)
    print(f"Saved {len(hierarchy)} hierarchy paths")
    print("Done!")

if __name__ == '__main__':
    main()
